factorial.code:
// A method is a function stored in a frame slot. :Factorial(...)
// sends the message to self, the frame that received the first send.
local calc := {
    Factorial: func(n)
        if n <= 1 then 1 else n * :Factorial(n - 1)
};

Print(calc:Factorial(10) & "\n");

